package cz.zamerovac.app;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;

/** Durable per-installation/per-store record of committed messages, never restored onto another identity. */
final class CloudInbox {
 private static final Object LOCK=new Object();private static final java.util.Map<String,Long> GENERATIONS=new java.util.HashMap<>();private JSONObject cached;private long cachedGeneration=-1,cachedSize=-1,cachedModified=-1;private final AtomicFile file;private final String owner,namespace;
 CloudInbox(File noBackup,String owner,String namespace)throws Exception{if(!DeviceIdentity.valid(owner))throw new IOException("Neplatná identita příjemce");this.owner=owner;this.namespace=PeerWire.hash(namespace.getBytes(StandardCharsets.UTF_8));file=new AtomicFile(new File(noBackup,"sync-inbox-v2-"+owner+"-"+this.namespace+".json"));}
 private String key(String peer,String name)throws IOException{if(!DeviceIdentity.valid(peer)||name==null||!name.matches("[a-f0-9]{64}-[a-f0-9-]{36}\\.json"))throw new IOException("Neplatná zpráva inboxu");return peer+"/"+name;}
 private JSONObject load()throws Exception{
  File target=file.getBaseFile();long generation=GENERATIONS.getOrDefault(target.getAbsolutePath(),0L);if(cached!=null&&cachedGeneration==generation&&cachedSize==target.length()&&cachedModified==target.lastModified())return cached;if(!target.exists()&&!new File(target+".bak").exists())return new JSONObject().put("version",2).put("owner",owner).put("namespace",namespace).put("messages",new JSONObject());if(target.length()>PeerWire.MAX_JSON||new File(target+".bak").length()>PeerWire.MAX_JSON)throw new IOException("Index přijatých zpráv je příliš velký");JSONObject data=JsonInput.object(file.readFully());if(data.optInt("version")!=2||!owner.equals(data.optString("owner"))||!namespace.equals(data.optString("namespace"))||data.getJSONObject("messages").length()>100000)throw new IOException("Neplatný index přijatých zpráv");cached=data;cachedGeneration=generation;cachedSize=target.length();cachedModified=target.lastModified();return data;
 }
 private void save(JSONObject data)throws Exception{byte[] bytes=data.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>PeerWire.MAX_JSON)throw new IOException("Index přijatých zpráv je příliš velký");FileOutputStream out=null;try{out=file.startWrite();out.write(bytes);out.getFD().sync();file.finishWrite(out);out=null;if(!java.util.Arrays.equals(bytes,file.readFully()))throw new IOException("Index přijatých zpráv nebyl potvrzen");File target=file.getBaseFile();long generation=GENERATIONS.getOrDefault(target.getAbsolutePath(),0L)+1;GENERATIONS.put(target.getAbsolutePath(),generation);cached=new JSONObject(data.toString());cachedGeneration=generation;cachedSize=target.length();cachedModified=target.lastModified();}catch(Exception error){if(out!=null)file.failWrite(out);throw error;}}
 JSONObject get(String peer,String name)throws Exception{synchronized(LOCK){JSONObject entry=load().getJSONObject("messages").optJSONObject(key(peer,name));if(entry==null)return null;String hash=entry.getString("hash");if(!name.startsWith(hash+"-")||!hash.matches("[a-f0-9]{64}")||PeerSnapshot.integer(entry,"size",PeerWire.MAX_JSON)<1||!(entry.get("acked") instanceof Boolean))throw new IOException("Poškozený index přijaté zprávy");return new JSONObject(entry.toString());}}
 void committed(String peer,String name,String hash,long size)throws Exception{synchronized(LOCK){String key=key(peer,name);if(!hash.matches("[a-f0-9]{64}")||!name.startsWith(hash+"-")||size<1||size>PeerWire.MAX_JSON)throw new IOException("Neplatné potvrzení inboxu");JSONObject data=new JSONObject(load().toString()),messages=data.getJSONObject("messages");JSONObject existing=messages.optJSONObject(key);if(existing!=null){if(!hash.equals(existing.getString("hash"))||size!=existing.getLong("size"))throw new IOException("Změněná neměnná zpráva");return;}messages.put(key,new JSONObject().put("hash",hash).put("size",size).put("acked",false));save(data);}}
 void acknowledged(String peer,String name)throws Exception{synchronized(LOCK){JSONObject data=new JSONObject(load().toString()),entry=data.getJSONObject("messages").optJSONObject(key(peer,name));if(entry==null)throw new IOException("Bez uložených dat nelze potvrdit zprávu");entry.put("acked",true);save(data);}}
}
